using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class ComplaintsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Complaints", "View"); return AdminDataService.GetList("Complaints"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Complaints", "View"); return AdminDataService.GetDefinitionMetadata("Complaints"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Complaints", "Delete"); return AdminDataService.Delete("Complaints", id); } } }
